import { ToolCall, ToolDefinition, ToolResult } from '../types';

/**
 * Standard conversational participant role across modern LLMs.
 * - 'user': Message originating from human or external participant.
 * - 'assistant': Message generated by the AI model.
 */
export type ChatRole = 'user' | 'assistant';

/**
 * Single turn in short-term conversation history.
 */
export interface ChatMessage {
  /** Role indicating who produced this message. */
  role: ChatRole;
  /** Text content of the conversation turn. */
  content: string;
}

/**
 * Universal payload sent to an LLM provider to request text generation or function calling.
 * Completely vendor-agnostic; providers map these fields to their respective SDK formats.
 */
export interface LLMRequest {
  /** Persona and system instructions directing the model's behavior and tone. */
  systemInstruction: string;
  /** Main prompt text from the current user message turn. */
  prompt: string;
  /** Recent chronological conversation turns for conversational context. */
  conversationHistory?: ChatMessage[];
  /** Declarations of tools available for the model to invoke. */
  tools?: ToolDefinition[];
  /** Optional inline media attachments (e.g. images) for multimodal processing. */
  images?: { data: Buffer | string; mimeType: string }[];
  /** Optional flag to enable real-time search grounding if supported by provider. */
  enableSearchGrounding?: boolean;
  /** Optional model identifier override (e.g. for fallback failover). */
  modelName?: string;
}

/**
 * Normalized result produced by an LLM provider.
 */
export interface LLMResult {
  /** Natural language response text produced by the model. */
  text: string;
  /** List of tool calls requested by the model during this turn, if any. */
  toolCalls?: ToolCall[];
  /** Web sources or grounding citations returned by the model. */
  sources?: { title: string; url: string }[];
}

/**
 * Payload sent to an LLM provider to continue generation after executing tool calls.
 */
export interface ContinuationRequest {
  /** Original LLMRequest that initiated the tool call turn. */
  originalRequest: LLMRequest;
  /** Tool calls that were requested and executed. */
  toolCalls: ToolCall[];
  /** Outputs resulting from the executed tool calls. */
  toolResults: ToolResult[];
  /** Optional model identifier to switch models (e.g. for fallback or multi-hop routing). */
  modelName?: string;
  /** Opaque provider-specific session state (e.g. cached SDK contents or message arrays). */
  sessionState?: unknown;
}

/**
 * Result of tool continuation, containing the new model output and updated session state.
 */
export interface ContinuationResult extends LLMResult {
  /** Updated opaque session state to thread into subsequent hops if multi-hop continues. */
  sessionState?: unknown;
}

/**
 * Contract that every LLM provider adapter must implement.
 * Isolates vendor SDK specifics (Google GenAI, OpenAI, Anthropic, Ollama, etc.) from the core agent.
 */
export interface LLMProvider {
  /** Unique provider identifier (e.g. "gemini", "openai"). */
  readonly id: string;
  /** Human-readable display name of the provider. */
  readonly name: string;
  /** Name of the active model being targeted (e.g. "gemini-3.1-flash-lite", "gpt-4o"). */
  readonly modelName?: string;

  /**
   * Generates a conversational response or tool calls based on the provided request.
   */
  generate(request: LLMRequest): Promise<LLMResult>;

  /**
   * Continues generation by supplying executed tool outputs back to the model.
   * Required for multi-hop ReAct tool execution workflows.
   */
  continueWithToolResults?(request: ContinuationRequest): Promise<ContinuationResult>;
}

/**
 * Contract that every vector embedding provider adapter must implement.
 * Isolates vendor embedding SDKs from the core memory and semantic search subsystems.
 */
export interface EmbeddingProvider {
  /** Unique provider identifier (e.g. "gemini-embedding", "openai-embedding"). */
  readonly id: string;
  /** Human-readable display name. */
  readonly name: string;
  /** Active embedding model identifier (e.g. "gemini-embedding-001"). */
  readonly modelName?: string;

  /**
   * Generates a numerical vector embedding for the given input text.
   */
  getEmbedding(text: string): Promise<number[]>;
}


/**
 * Result score of a probabilistic decision evaluation.
 */
export interface DecisionScore {
  /** Probability value between 0.0 and 1.0. */
  probability: number;
  /** Optional confidence score from the decision engine. */
  confidence?: number;
}

/**
 * Contract that every decision evaluation provider must implement.
 * Isolates decision/classification SDKs (such as Gemini Decisions API) from core evaluation logic.
 */
export interface DecisionProvider {
  /** Unique provider identifier (e.g. "gemini-decision"). */
  readonly id: string;
  /** Human-readable display name. */
  readonly name: string;
  /** Active decision model identifier (e.g. "gemini-decision-1"). */
  readonly modelName?: string;

  /**
   * Evaluates a decision given an input context and instructions.
   */
  evaluateDecision(input: string, instructions: string): Promise<DecisionScore | null>;
}
